import openpyxl

# Look at all three variants' destination sheets
for variant in ['a', 'b', 'c']:
    wb = openpyxl.load_workbook(f'data/workbooks/working_paper_variant_{variant}.xlsx', data_only=True)
    ws = wb['destination']
    print(f"\n=== Variant {variant} destination ===")
    print(f"  Dimensions: {ws.dimensions}")
    for row_idx in range(1, ws.max_row + 1):
        row_data = []
        for col in range(1, ws.max_column + 1):
            cell = ws.cell(row=row_idx, column=col)
            if cell.value is not None:
                row_data.append((cell.coordinate, cell.value))
        if row_data:
            print(f"  Row {row_idx}: {row_data}")

    # Check lap sheets block counts
    for sheet_name in ['lap-1', 'lap-2', 'lap-9']:
        if sheet_name in wb.sheetnames:
            ws2 = wb[sheet_name]
            blocks = 0
            for row_idx in range(1, ws2.max_row + 1):
                cell_val = ws2.cell(row=row_idx, column=1).value
                if cell_val and 'Working Paper' in str(cell_val):
                    blocks += 1
            print(f"  {sheet_name}: {blocks} blocks")

    wb.close()
