import openpyxl

# Check if any cells in lap sheets contain formulas
wb = openpyxl.load_workbook('data/workbooks/working_paper_variant_a.xlsx', data_only=False)

for sheet_name in ['lap-1', 'lap-2', 'lap-9']:
    ws = wb[sheet_name]
    formula_count = 0
    for row in ws.iter_rows(min_row=1, max_row=ws.max_row, max_col=ws.max_column):
        for cell in row:
            if isinstance(cell.value, str) and cell.value.startswith('='):
                formula_count += 1
                if formula_count <= 5:
                    print(f"{sheet_name} {cell.coordinate}: {cell.value}")
    print(f"{sheet_name} total formulas: {formula_count}")

wb.close()
